function link(input, title = input) { const url = safeUrl(input); return url ? `<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${text(title)}</a>` : `<span>${text(title)}</span>`; }
function safeColor(input) { return /^#[0-9a-f]{3}(?:[0-9a-f]{3})?$/i.test(value(input).trim()) ? value(input).trim() : '#20564b'; }
