function metric(input, unit = '') { const n = typeof input === 'object' ? input?.median ?? input?.p75 ?? input?.value : input; return Number.isFinite(Number(n)) && n !== null && n !== undefined ? `${Number(n).toLocaleString('en-US', { maximumFractionDigits: unit === '' ? 3 : 0 })}${unit}` : '—'; }
