const SCRIPT = `
(() => {
  const cards = Array.from(document.querySelectorAll('.finding'));
  const controls = ['finding-search', 'category-filter', 'priority-filter', 'kind-filter'].map(id => document.getElementById(id));
  const status = document.getElementById('filter-status');
  const noResults = document.getElementById('no-results');
  function apply() {
    const [query, category, priority, kind] = controls.map(control => control.value.trim().toLowerCase());
    let visible = 0;
    cards.forEach(card => {
      const show = (!query || card.textContent.toLowerCase().includes(query)) && (!category || card.dataset.category.toLowerCase() === category) && (!priority || card.dataset.priority === priority) && (!kind || card.dataset.kind === kind);
      card.hidden = !show;
      if (show) visible++;
    });
    status.textContent = 'Showing ' + visible + ' of ' + cards.length + ' findings';
    noResults.hidden = visible > 0 || cards.length === 0;
  }
  controls.forEach(control => control.addEventListener(control.tagName === 'INPUT' ? 'input' : 'change', apply));
  document.getElementById('print-report').addEventListener('click', () => window.print());
  function revealAnchor() {
    if (!window.location.hash) return;
    let target;
    try { target = document.getElementById(decodeURIComponent(window.location.hash.slice(1))); } catch { return; }
    if (target && target.classList.contains('finding') && target.hidden) { controls.forEach(control => { control.value = ''; }); apply(); target.scrollIntoView(); }
  }
  window.addEventListener('hashchange', revealAnchor);
  const openedForPrint = [];
  window.addEventListener('beforeprint', () => { document.querySelectorAll('details:not([open])').forEach(detail => { openedForPrint.push(detail); detail.open = true; }); });
  window.addEventListener('afterprint', () => { openedForPrint.splice(0).forEach(detail => { detail.open = false; }); });
  apply(); revealAnchor();
})();
`;

/** Build a portable branded report from the audit evidence model. No external assets are loaded. */
export function renderReport(audit = {}) {
  const findings = orderedFindings(audit), caps = capabilities(audit), brand = audit.brand || {};
  let host = ''; try { host = new URL(value(audit.target)).hostname; } catch { /* Missing target is explicit. */ }
  const name = value(brand.name) || host || 'Website';
  const initials = name.split(/\s+/).filter(Boolean).slice(0, 2).map(word => word[0]).join('').toUpperCase() || 'W';
  const logo = safeLogo(brand.logoDataUrl), issues = findings.filter(i => i.kind === 'issue'), early = findings.filter(i => ['p0', 'p1'].includes(i.priority));
  const gaps = caps.filter(i => i.status !== 'complete'), categories = [...new Set(findings.map(i => i.category))].sort();
  const executive = findings.slice(0, 5).map((i, index) => `<div class="decision"><span class="decision-number">${String(index + 1).padStart(2, '0')}</span><div><h3><a href="#${i.anchor}">${esc(i.title)}</a></h3><p>${esc(i.recommendation)}</p><p class="decision-owner">${esc(i.owner)} · ${esc(label(i.effort))} effort · ${i.evidence.length} evidence items</p></div>${pill(i.priority.toUpperCase(), i.priority)}</div>`).join('');
  const nav = [['overview', '01', 'Executive decisions'], ['groups', '02', 'Related observations'], ['roadmap', '03', '90-day action plan'], ['coverage', '04', 'Coverage & limitations'], ['areas', '05', 'Audit workstreams'], ['findings', '06', 'Detailed findings'], ['inventory', '07', 'Page inventory'], ['methodology', '08', 'Methodology & sources']];
  const filter = `<noscript><p class="noscript-note">JavaScript is disabled. All findings remain readable; interactive filtering is unavailable.</p></noscript><div class="filter-bar"><label for="finding-search">Search findings<input id="finding-search" type="search" placeholder="Title, URL, evidence, or owner…"></label><label for="category-filter">Workstream<select id="category-filter"><option value="">All workstreams</option>${categories.map(c => `<option value="${esc(c)}">${esc(label(c))}</option>`).join('')}</select></label><label for="priority-filter">Priority<select id="priority-filter"><option value="">All priorities</option>${PRIORITIES.map(p => `<option value="${p}">${p.toUpperCase()}</option>`).join('')}</select></label><label for="kind-filter">Finding type<select id="kind-filter"><option value="">All finding types</option>${KINDS.map(k => `<option value="${k}">${label(k)}</option>`).join('')}</select></label></div><div id="filter-status" class="filter-status" role="status" aria-live="polite">Showing ${findings.length} of ${findings.length} findings</div><div id="no-results" class="empty" hidden>No findings match these filters.</div>`;
  const comparison = audit.comparison ? `<div class="subsection"><h3>Comparison with a previous run</h3><p class="method-note">Confirm comparable settings and evidence periods before attributing changes to implementation.</p><pre>${text(audit.comparison)}</pre></div>` : '';
  return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="referrer" content="no-referrer"><title>${esc(name)} | Website visibility audit</title><style>${CSS.replace('BRAND_COLOR', safeColor(brand.primaryColor))}</style></head><body><a href="#overview" class="skip-link">Skip to report</a><div class="layout"><aside class="sidebar"><div class="brand-lockup">${logo ? `<img class="brand-logo" src="${esc(logo)}" alt="${esc(name)} logo">` : `<div class="brand-initials" aria-hidden="true">${esc(initials)}</div>`}<div><div class="brand-name">${esc(name)}</div><div class="brand-caption">Visibility audit</div></div></div><div class="side-rule"></div><span class="nav-label">In this report</span><nav aria-label="Report sections">${nav.map(([id, n, title]) => `<a href="#${id}"><span>${n}</span>${title}</a>`).join('')}</nav><div class="side-footer"><strong>Evidence before assumptions.</strong>Decisions, implementation, and verification in one report.<br><br>${esc(host || 'Target not recorded')}</div></aside><main class="main"><div class="utility"><span>Website visibility intelligence</span><button type="button" id="print-report" class="print-button">Print / Save PDF</button></div><header class="hero">${logo ? `<img class="print-brand" src="${esc(logo)}" alt="${esc(name)} logo">` : ''}<span class="eyebrow">${esc(name)} · Website audit</span><h1>A clearer path to<br>search visibility.</h1><p class="hero-description">Technical SEO, content, performance, authority, and AI search findings translated into a prioritized implementation plan for ${esc(name)}.</p><div class="hero-meta"><span>Website <strong>${link(audit.target, host || audit.target || 'Not recorded')}</strong></span><span>Completed <strong>${esc(date(audit.completedAt, audit.timezone))}</strong></span><span>Run <strong>${text(audit.runId)}</strong></span></div></header><div class="score-strip" aria-label="Audit summary"><div class="stat"><strong>${number(audit.coverage?.crawled)}</strong><span>Pages crawled</span><small>${number(audit.coverage?.discovered)} discovered</small></div><div class="stat stat-critical"><strong>${early.length}</strong><span>Items needing early review</span><small>P0 and P1 priorities</small></div><div class="stat"><strong>${issues.length}</strong><span>Reported issues</span><small>${findings.filter(i => i.kind === 'hypothesis').length} hypotheses · ${findings.filter(i => i.kind === 'opportunity').length} opportunities</small></div><div class="stat"><strong>${caps.length ? gaps.length : '—'}</strong><span>Limited coverage areas</span><small>${caps.length ? 'Sampled, unassessed, or unavailable' : 'Capability ledger not supplied'}</small></div></div>
${section('overview', '01 / Decisions', 'Start with the decisions that matter.', 'Review these items first. Confidence and supporting evidence remain visible throughout the report.', `${strategyMarkup(audit)}<div class="decision-list">${executive || empty('No findings were recorded. Check coverage before drawing conclusions about site health.')}</div><div class="download-bar"><a href="action-plan.md" download>Download implementation plan ↗</a><a href="findings.csv" download>All findings · CSV ↗</a><a href="audit.json" download>Audit evidence · JSON ↗</a></div>${comparison}`)}
${section('groups', '02 / Investigation', 'Related observations, fewer disconnected tasks.', '', groupsMarkup(findings))}
${section('roadmap', '03 / Delivery', 'A practical 30 / 60 / 90-day plan.', '', roadmapMarkup(findings))}
${section('coverage', '04 / Confidence', 'What was assessed. What remains unknown.', 'Coverage gaps and missing evidence are reported separately from detected issues.', coverageMarkup(audit, caps))}
${section('areas', '05 / Workstreams', 'One audit. Connected areas of improvement.', '', areasMarkup(findings, caps) + performanceMarkup(audit) + datasetsMarkup(audit))}
${section('findings', '06 / Evidence & execution', 'The complete findings register.', 'Each finding connects the observation to an action, owner, dependencies, and verification criteria.', `${filter}<div class="findings">${findings.map(item => findingMarkup(item, audit)).join('') || empty('There are no recorded findings in this audit.')}</div>`)}
${section('inventory', '07 / Pages', 'The pages behind the analysis.', '', inventoryMarkup(audit))}
${section('methodology', '08 / Transparency', 'Methodology, provenance, and limits.', '', sourcesMarkup(audit))}
<footer class="footer"><span>${esc(name)} · Website visibility audit</span><span>Based on recorded evidence · ${esc(value(audit.runId, 'Run not recorded'))}</span></footer></main></div><script>${SCRIPT}</script></body></html>`;
}

function csvCell(input) {
  let output = value(input);
  if (/^[\s\u0000-\u001f]*[=+\-@]/.test(output) || /^[\t\r\n]/.test(output)) output = `'${output}`;
  return `"${output.replace(/"/g, '""')}"`;
}
function csv(headers, rows) { return `\uFEFF${[headers, ...rows].map(row => row.map(csvCell).join(',')).join('\r\n')}\r\n`; }
function md(input) { return value(input).replace(/\\/g, '\\\\').replace(/[<>]/g, c => c === '<' ? '&lt;' : '&gt;').replace(/([\[\]`*_{}|])/g, '\\$1').replace(/\r?\n/g, '\n  '); }
function mdUrl(input) { const url = safeUrl(input); return url ? `<${url.replace(/</g, '%3C').replace(/>/g, '%3E')}>` : md(input); }

/** Implementation tickets share the report's evidence and priorities. */
export function renderActionPlan(audit = {}) {
  const findings = orderedFindings(audit), name = value(audit.brand?.name) || value(audit.target) || 'Website';
  const lines = [`# ${md(name)} — implementation action plan`, '', `Target: ${mdUrl(audit.target || 'Not recorded')}`, '', `Run: ${md(audit.runId || 'Not recorded')} · Completed: ${md(date(audit.completedAt, audit.timezone))}`, '', 'This backlog is derived from the same evidence as report.html and findings.csv. Suggested windows guide sequencing; they are not delivery commitments or ranking guarantees. Confirm effort, dependencies, access, and business priority before scheduling.', '', '## Suggested delivery sequence', '', '| Window | Priority | Items |', '| --- | --- | ---: |', `| First 30 days; P0 needs immediate review | P0 + P1 | ${findings.filter(i => ['p0', 'p1'].includes(i.priority)).length} |`, `| Days 31–60 | P2 | ${findings.filter(i => i.priority === 'p2').length} |`, `| Days 61–90 | P3 | ${findings.filter(i => i.priority === 'p3').length} |`, ''];
  const a = audit.analysis || {}, context = a.businessContext || {};
  if (a.executiveSummary || Object.keys(context).length) {
    lines.push('## Site-specific analysis', '', md(a.executiveSummary || 'No executive narrative supplied.'), '');
    for (const [key, content] of Object.entries(context)) lines.push(`- ${md(label(key))}: ${md(content)}`);
    lines.push('');
  }
  const actions = [...list(a.contentActions).map(i => ({ ...i, type: 'Content' })), ...list(a.strategicActions).map(i => typeof i === 'object' && i ? { ...i, type: 'Strategy' } : { action: value(i), type: 'Strategy' })];
  if (actions.length) {
    lines.push('## Content and strategy decisions', '');
    actions.forEach((i, index) => lines.push(`### ${index + 1}. ${md(i.type)}: ${md(i.action || i.recommendation || i.title || 'Decision to review')}`, '', `- Priority: ${md(i.priority || 'Not assigned')}`, `- URL: ${mdUrl(i.url || 'Not specified')}`, `- Reason: ${md(i.reason || 'Not supplied')}`, `- Evidence: ${md(i.evidence || 'Not supplied; validate before execution')}`, ''));
  }
  lines.push('## Developer and content tickets', '');
  if (!findings.length) lines.push('No findings were supplied. Review assessment coverage; an empty backlog does not establish that the website passed all checks.', '');
  for (const i of findings) {
    lines.push(`### ${i.priority.toUpperCase()} · ${md(i.id)} · ${md(i.title)}`, '', `- Type: ${md(i.kind)}; severity: ${md(i.severity)}; confidence: ${md(i.confidence)}.`, `- Workstream: ${md(i.category)}.`, `- Owner: ${md(i.owner)}.`, `- Effort: ${md(i.effort)}.`, `- Dependencies: ${i.dependencies.length ? i.dependencies.map(md).join(', ') : 'None recorded'}.`, `- HTML evidence: [Open finding](report.html#${i.anchor}).`, '', '**Change to implement**', '', md(i.recommendation), '', '**Affected URLs**', '', ...(i.affectedUrls.length ? i.affectedUrls.map(url => `- ${mdUrl(url)}`) : ['No affected URL list was supplied.']), '', '**Evidence**', '');
    if (i.priorityReason) lines.push('Priority rationale: ' + md(i.priorityReason), '');
    if (i.impact) lines.push('Observed impact evidence: ' + md(i.impact) + '. Do not sum overlapping finding metrics into forecasts.', '');
    for (const e of i.evidence) {
      lines.push(`- URL: ${mdUrl(e.url || 'Not recorded')}`);
      for (const key of ['observed', 'expected', 'detail', 'source']) if (e[key] !== undefined) lines.push(`  - ${label(key)}: ${md(e[key])}`);
    }
    if (!i.evidence.length) lines.push('No supporting evidence was supplied. Validate this finding before implementation.');
    lines.push('', '**Acceptance criteria**', '', ...(i.acceptance.length ? i.acceptance.map(item => `- [ ] ${md(item)}`) : ['- [ ] Define a measurable acceptance criterion with the owner before making changes.']), '', '**Implementation and verification checklist**', '', '- [ ] Review the affected scope and protect intentional exceptions.', '- [ ] Prepare a source/CMS change or reviewable patch with a rollback method.', '- [ ] Validate in a suitable test environment where available.', '- [ ] Apply the authorized change and repeat the relevant checks.', '- [ ] Confirm no regression in status, canonical, directives, links, or page behavior.', '- [ ] Record the change date and measure outcomes against the baseline.', '', '---', '');
  }
  lines.push('## Coverage and remaining evidence', '');
  const caps = capabilities(audit);
  lines.push(...(caps.length ? caps.map(i => `- ${md(i.label)}: ${md(label(i.status))}. ${md(i.detail || 'No scope details supplied.')}`) : ['No capability ledger was supplied. Unassessed areas must not be treated as passes.']));
  return `${lines.join('\n')}\n`;
}

/** Write HTML, all finding/page rows, and developer tickets. The caller writes audit.json. */
export async function writeReport(audit = {}, outputDir, { pdf = false, browserExecutable } = {}) {
  if (!outputDir) throw new TypeError('An output directory is required.');
  const directory = path.resolve(outputDir);
  await mkdir(directory, { recursive: true });
  const findings = orderedFindings(audit);
  const files = { html: path.join(directory, 'report.html'), findingsCsv: path.join(directory, 'findings.csv'), pagesCsv: path.join(directory, 'pages.csv'), actionPlan: path.join(directory, 'action-plan.md') };
  const headers = ['id', 'checkId', 'title', 'category', 'severity', 'kind', 'confidence', 'priority', 'priorityInferred', 'owner', 'effort', 'affectedUrlCount', 'affectedUrls', 'recommendation', 'acceptance', 'dependencies', 'evidence'];
  const rows = findings.map(i => { const row = { ...i, affectedUrlCount: i.affectedUrls.length, affectedUrls: i.affectedUrls.join('\n'), acceptance: i.acceptance.map(e => value(e)).join('\n'), dependencies: i.dependencies.map(e => value(e)).join('\n'), evidence: JSON.stringify(i.evidence) }; return headers.map(h => row[h]); });
  const pageHeaders = ['url', 'finalUrl', 'status', 'responseTitle', 'responseDescription', 'responseH1', 'responseCanonical', 'responseWordCount', 'renderedTitle', 'renderedDescription', 'renderedH1', 'renderedCanonical', 'renderedWordCount', 'indexable', 'robots', 'contentType'];
  const pageRows = list(audit.pages).map(p => pageHeaders.map(h => {
    const prefix = h.startsWith('response') ? 'response' : h.startsWith('rendered') ? 'rendered' : '';
    const key = prefix ? h.slice(prefix.length).replace(/^./, c => c.toLowerCase()) : h;
    const source = prefix === 'rendered' ? p.rendered || {} : p;
    return ['h1', 'canonical', 'robots'].includes(key) ? list(source[key]).map(e => value(e)).join('\n') : source[key];
  }));
  await Promise.all([writeFile(files.html, renderReport(audit), 'utf8'), writeFile(files.findingsCsv, csv(headers, rows), 'utf8'), writeFile(files.pagesCsv, csv(pageHeaders, pageRows), 'utf8'), writeFile(files.actionPlan, renderActionPlan(audit), 'utf8')]);
  if (pdf) {
    let browser;
    try {
      const { chromium } = await import('playwright');
      browser = await chromium.launch({ headless: true, ...(browserExecutable ? { executablePath: browserExecutable } : {}) });
      const page = await browser.newPage();
      const { pathToFileURL } = await import('node:url');
      await page.goto(pathToFileURL(files.html).href, { waitUntil: 'load' });
      await page.emulateMedia({ media: 'print' });
      await page.evaluate(() => { document.querySelectorAll('details').forEach(d => { d.open = true; }); });
      const pdfPath = path.join(directory, 'report.pdf');
      await page.pdf({ path: pdfPath, format: 'A4', printBackground: true, preferCSSPageSize: true });
      files.pdf = pdfPath;
    } catch (error) {
      files.pdfError = `PDF was not generated: ${value(error?.message, value(error)).slice(0, 500)}. Use the HTML report's Print / Save PDF option.`;
    } finally { if (browser) await browser.close().catch(() => {}); }
  }
  return files;
}
